<section class="panel table-panel"><form class="filter-bar" method="get"><input type="hidden" name="r" value="results"><div class="search-filter"><span>⌕</span><input name="q" value="<?=e($_GET['q']??'')?>" placeholder="Nom, ville, téléphone…"></div><select name="status"><option value="">Tous les statuts</option><?php foreach(['nouveau','a_contacter','contacte','interesse','rdv','client','refuse'] as $s):?><option value="<?=$s?>" <?=($_GET['status']??'')===$s?'selected':''?>><?=e(status_label($s))?></option><?php endforeach;?></select><select name="category"><option value="">Toutes catégories</option><?php foreach($categories as $c):?><option value="<?=e($c['label'])?>" <?=($_GET['category']??'')===$c['label']?'selected':''?>><?=e($c['label'])?></option><?php endforeach;?></select><label class="inline-check"><input type="checkbox" name="phone" value="1" <?=!empty($_GET['phone'])?'checked':''?>> Téléphone</label><label class="inline-check"><input type="checkbox" name="email" value="1" <?=!empty($_GET['email'])?'checked':''?>> Email</label><button class="button secondary small">Filtrer</button></form>
<form method="post" action="?r=bulk" id="bulk-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><div class="bulkbar"><span><b id="selected-count">0</b> sélectionné(s)</span><select name="action"><option value="">Action groupée…</option><option value="a_contacter">Déplacer vers À contacter</option><option value="contacte">Marquer Contacté</option><option value="interesse">Marquer Intéressé</option><option value="export">Exporter la sélection</option><option value="delete">Supprimer</option></select><button class="button secondary small" type="submit">Appliquer</button><a class="text-link" href="?r=export">Exporter tout en CSV ↓</a></div><div class="table-scroll"><table><thead><tr><th><input type="checkbox" id="select-all"></th><th>Établissement</th><th>Coordonnées</th><th>Localisation</th><th>Site web</th><th>Confiance</th><th>Statut</th><th></th></tr></thead><tbody><?php if(!$prospects):?><tr><td colspan="8"><div class="empty-small">Aucun prospect ne correspond à vos filtres. <a href="?r=search">Lancer une recherche</a></div></td></tr><?php endif;foreach($prospects as $p):?><tr><td><input type="checkbox" class="row-check" name="ids[]" value="<?=$p['id']?>"></td><td><a class="business-link" href="?r=prospect&id=<?=$p['id']?>"><?=e($p['nom'])?></a><small class="table-sub"><?=e($p['categorie'])?></small></td><td><?php if($p['telephone_normalise']):?><a href="tel:<?=e($p['telephone_normalise'])?>"><?=e($p['telephone']?:$p['telephone_normalise'])?></a><?php else:?><span class="muted">—</span><?php endif;?><?php if($p['email']):?><small class="table-sub"><?=e($p['email'])?></small><?php endif;?></td><td><?=e(trim(($p['adresse']??'').' · '.($p['ville']??''),' ·'))?><small class="table-sub"><?=e($p['code_postal'])?></small></td><td><span class="badge <?=($p['site_web_statut']==='reseaux_sociaux'?'social':'no-site')?>"><?= $p['site_web_statut']==='reseaux_sociaux'?'Réseaux sociaux':'Aucun'?></span></td><td><span class="confidence confidence-<?=e($p['score_confiance'])?>"><?=e(ucfirst($p['score_confiance']))?></span></td><td><span class="badge status-<?=$p['statut_prospection']?>"><?=e(status_label($p['statut_prospection']))?></span></td><td><a class="icon-link" href="?r=prospect&id=<?=$p['id']?>" title="Ouvrir">↗</a></td></tr><?php endforeach;?></tbody></table></div><div class="table-foot">Affichage limité aux 500 derniers prospects correspondant aux critères.</div></form></section>
